    "content": "文章系原创首发，文责自负。 这段时间，我在简书的更文时常断更，有时候是我忘记了，有时候是我故意的，实在没有写了，就不写，好在有补充卡，个六七天可以用一次，我便偷懒耍滑，偶尔漏更。 好几次好似是系统问题，手机打开简书，登录不上，也不知道为什么，总之是断更了，不过都有补救卡，也算没有断更。 我发现我的持续力不足了，写着写着就偷懒了，没后劲。 前几天，翻了一下，我以前的存文，发现有好几个小说，开了几段头，没有结尾了，属于断掉的小说。 那时，信心满满，感觉自己可以试着写小说，结果越写越干涩，没有灵感新意，慢慢地就放弃啦。 …"
