    "description": "深夜十一点半，21岁的“秒回师”陈欣（化名）接到一个订单。 电话那头是一名年轻女性。接通后，听筒里只传来阵阵杂音，无论陈欣如何搭话，对方始终没有回应。约一个小时后，通话结束，对方给她发来一条消息：“谢谢你陪着我。” 这发生在2026年1月的一幕，是陈欣的工作日常。陈欣告诉记者，“秒回师”并不是一个正式的职业概念。顾名思义，这份工作要求在客户下单后，及时回应对方的情绪倾诉。 陈欣的经历，是情绪陪伴类新业态快速兴起的一个缩影。记者调查发现，…",
    "content": "深夜十一点半，21岁的“秒回师”陈欣（化名）接到一个订单。 电话那头是一名年轻女性。接通后，听筒里只传来阵阵杂音，无论陈欣如何搭话，对方始终没有回应。约一个小时后，通话结束，对方给她发来一条消息：“谢谢你陪着我。” 这发生在2026年1月的一幕，是陈欣的工作日常。陈欣告诉记者，“秒回师”并不是一个正式的职业概念。顾名思义，这份工作要求在客户下单后，及时回应对方的情绪倾诉。 陈欣的经历，是情绪陪伴类新业态快速兴起的一个缩影。记者调查发现，近年来，以“秒回师”“倾听师”“树洞”等为名的情绪陪伴服务涌现。这一新兴业态游走…"
