    "content": "9月8日，OpenAI公开了一份千禧年数学难题——纳维-斯托克斯方程存在性与光滑性问题的解答：约1万个AI智能体协同工作88小时，给出解析证明，随后由GPT-6 Astra用Lean完成形式化验证。目前该证明仍有待数学界进一步审查。 与此同时，这项成果也引发优先权争议：纽约大学数学家Tristan Buckmaster质疑OpenAI在获悉同行研究进展后加速推进，并担忧其此前与Codex的草稿数据可能被利用。 三天后，陶哲轩等25位菲尔兹奖得主联名发表声明称 ，AI公司推动把解决数学问题作为一种“基准”（bench…"
