    "author": "澎湃新闻记者 张静",
    "description": "从迪拜龙城的小商品贸易，到中国新能源汽车产业的纵深布局，再到无人机送外卖，在迪拜生活了10年的李敏，见证了中国企业出海的变迁。中企出海已从产品输出跃迁为技术和资本能力输出。 2025年，中国位居迪拜全球第一大贸易伙伴，与迪拜非石油贸易额约990亿美元。在不少人的印象中，中东似乎“遍地黄金”。但李敏发现，如今的迪拜“慢慢在内卷”——中国人卷，迪拜本地人也在卷，抱着“先来看看、说不定能成”的心态涌入，往往会发现出海远比想象复杂。 从小商品出…",
    "content": "从迪拜龙城的小商品贸易，到中国新能源汽车产业的纵深布局，再到无人机送外卖，在迪拜生活了10年的李敏，见证了中国企业出海的变迁。中企出海已从产品输出跃迁为技术和资本能力输出。 2025年，中国位居迪拜全球第一大贸易伙伴，与迪拜非石油贸易额约990亿美元。在不少人的印象中，中东似乎“遍地黄金”。但李敏发现，如今的迪拜“慢慢在内卷”——中国人卷，迪拜本地人也在卷，抱着“先来看看、说不定能成”的心态涌入，往往会发现出海远比想象复杂。 从小商品出海，到资本技术出海 1966年，法塔赫油田的发现，让迪拜迎来了勘探化石燃料30年…"
