    "content": "新华社华盛顿9月14日电（记者黄强 徐剑梅）美国总统特朗普14日在社交媒体发布多条帖文为其对伊朗政策辩护。特朗普称对与伊朗谈判持“开放”态度，并称美方在霍尔木兹海峡帮助石油运输，各国应对美进行“护航补偿”。 特朗普称，伊朗“迫切”希望达成协议，“我们对这一设想持开放态度”。此前，特朗普称，美伊战事将在11月美国国会中期选举完成后“立即结束”，同伊朗恢复谈判“并非我们目前考虑的事情”。 特朗普还称，全美普遍物价上涨不是他的责任，并将其归罪于拜登政府。他称，“除油价暂时处于高位外，其他物价正在大幅回落，一旦与伊朗的军事…"
