    "author": "果壳",
    "description": "今年7月，长沙，深夜一辆救护车把一名45岁男性送进了急诊室。 他深度昏迷，心率只有每分钟40次，两眼瞳孔一大一小。这是典型的脑疝表现，随时有生命危险。医院开通绿色通道，紧急开颅清除了血肿，才把人救回来。 这次严重摔伤，是他在家锻炼时发生的。他在免打孔门框单杠上倒立时，单杠突然滑脱，他头部重重着地。 对于急诊科医生，这已经不是第一次处理免打孔单杠造成的摔伤了。其他常见的“居家健身神器”，也曾多次出现在病历里：弹力带弹伤眼睛、摔下健身球骨折…",
    "content": "今年7月，长沙，深夜一辆救护车把一名45岁男性送进了急诊室。 他深度昏迷，心率只有每分钟40次，两眼瞳孔一大一小。这是典型的脑疝表现，随时有生命危险。医院开通绿色通道，紧急开颅清除了血肿，才把人救回来。 这次严重摔伤，是他在家锻炼时发生的。 他在免打孔门框单杠上倒立时，单杠突然滑脱，他头部重重着地。 对于急诊科医生，这已经不是第一次处理免打孔单杠造成的摔伤了。其他常见的“居家健身神器”，也曾多次出现在病历里：弹力带弹伤眼睛、摔下健身球骨折、转呼啦圈伤到内脏、跑步机烧伤手指…… 写出这些真实案例，绝不是为了给锻炼泼冷…"
