    "content": "新华社北京9月14日电（记者吴梦桐、曹嘉玥）外交部发言人郭嘉昆14日表示，人工智能的发展关乎全人类共同福祉。散播各种威胁叙事，不符合任何一方利益。 当日例行记者会上，有记者问：不久前，达里奥·阿莫迪、萨姆·奥尔特曼、埃隆·马斯克等呼吁人工智能企业放缓发展前沿技术。阿莫迪称，中国在人工智能领域保持领先，会对美国国家安全造成风险。外交部对此有何评论？ “人工智能的发展关乎全人类共同福祉，各方应共同推动人工智能开放、包容、普惠、向善。散播各种威胁叙事，搞对抗和恶性竞争，只会干扰人工智能全球治理进程，不符合任何一方利益。”…"
