    "description": "随着生成式AI从试验走向规模化部署，企业开始关注模型调用量、推理成本和投资回报率。但在Akamai大中华区副总裁张珂看来，Token成本不应只被视为财务问题，它也可能是识别AI安全事件的重要信号。 在近日的一场分享中，张珂表示，许多企业已经接入第三方大模型，或者建设了自有推理服务，却仍然缺少Token级别的成本观测能力。 当调用量异常增长时，企业往往只能看到月底账单上升，却难以及时判断这些Token究竟来自正常业务增长、低效应用设计，还…",
    "content": "随着生成式AI从试验走向规模化部署，企业开始关注模型调用量、推理成本和投资回报率。但在Akamai大中华区副总裁张珂看来，Token成本不应只被视为财务问题，它也可能是识别AI安全事件的重要信号。 &nbsp; 在近日的一场分享中，张珂表示，许多企业已经接入第三方大模型，或者建设了自有推理服务，却仍然缺少Token级别的成本观测能力。 &nbsp; 当调用量异常增长时，企业往往只能看到月底账单上升，却难以及时判断这些Token究竟来自正常业务增长、低效应用设计，还是API被盗用和恶意攻击。 &nbsp; 根据Aka…"
