    "description": "新华社北京9月14日电 题：8月金融数据出炉，释放哪些信息 新华社记者吴雨、任军 中国人民银行9月14日发布的金融统计数据显示，8月末，我国社会融资规模存量为464.8万亿元，同比增长7.2%；广义货币（M2）余额356.81万亿元，同比增长7.5%。 “当前我国金融总量合理增长，社会融资条件持续处于较为宽松的状态。”北京大学光华管理学院院长田轩说，目前我国社会融资规模、M2增速均在7%以上，与名义经济增速基本匹配，信用总量扩张并不弱，…",
    "content": "新华社北京9月14日电 题：8月金融数据出炉，释放哪些信息 新华社记者吴雨、任军 中国人民银行9月14日发布的金融统计数据显示，8月末，我国社会融资规模存量为464.8万亿元，同比增长7.2%；广义货币（M2）余额356.81万亿元，同比增长7.5%。 “当前我国金融总量合理增长，社会融资条件持续处于较为宽松的状态。”北京大学光华管理学院院长田轩说，目前我国社会融资规模、M2增速均在7%以上，与名义经济增速基本匹配，信用总量扩张并不弱，只是结构上发生了变化。 当前，债券、股票融资增长较快，成为实体经济获取资金的重要…"
