    "content": "新华社基辅9月14日电（记者李东旭）据乌克兰国际文传电讯社14日报道，乌克兰总统泽连斯基计划前往纽约与美国总统特朗普讨论乌俄实施海上停火和“能源停火”事宜。 泽连斯基当天在接受媒体采访时表示，乌方对与俄方实施海上停火和“能源停火”持开放态度，如果这与特朗普的安排不冲突，他将前往纽约与特朗普讨论相关事宜。 泽连斯基说，他计划本月21日至23日访问美国，“这很重要，是优先事项”。他希望能成行，有机会与美国和欧洲伙伴一道推动相关停火事宜。 泽连斯基此前表示，他计划9月与特朗普举行会晤并讨论弹道导弹防御问题。会晤后，乌方将…"
